Definition VSCR : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2'D!1,A|:000;!2'`R'b8'b9").

Theorem visit_key_nested_ok : forall (bs : list Z) (LBo : list (Z * Z)) (cr : credit) (sp r V S2 kx sv : Z) (g : eghost) (c0 : ectx) (r0 : estate),
  g_es g = c0 :: r0 ->
  PML.cps_heap L HI PC_VISIT_KEY r sp VSCR (LBo ++ g_lbv g) cr
    (fun R M => PML.entry L R M sp r VSCR /\ PML.a0 R V /\ PML.a1 R sv /\ True /\ sv_arg L LBo M sp V S2 sv bs /\ enc_inv M V S2 g /\ ev_guard (g_es g) (EvKey bs) /\
                PML.img_ro M /\ PML.lits_ok M /\ ecredit L cr g kx /\ objs_enc L sp V S2)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
